\includegraphics[width = 0.6\textwidth]{zp_xsec.pdf}
\caption{\it The production cross sections of the $Z^\prime$ boson as a function of $M_{Z^\prime}$ for different choices of $\beta$ at the 8~TeV LHC (a) and the 14~TeV LHC (b). For comparison we also plots the production cross section of a sequential $Z^\prime$ boson (SSM).}
\label{ppzp}
