\begin{table}\centering
\caption{Collider signature of $VV$ ($YY$) pair production for $\beta=\pm \sqrt{3}$ and lightest particle, where $R_h$ denotes $R$-hadron and can be found in Table~\ref{tbl:Rhadron}.}
\label{tbl:LLP}
\begin{tabular}{|c|c|c|c|}
\hline
